package main

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/mcpdev80/baseharbor/internal/application"
)

// These legacy positive fixtures use IDs generated by application.New. Move
// that identity to the same canonical Store used by explicit initialization;
// never manufacture an authored ID or let a read command initialize it.
func writeInitializedAuthoredManifest(t *testing.T, path string, m application.Manifest, mode os.FileMode) error {
	t.Helper()
	if err := os.WriteFile(path, []byte(m.AuthoredYAML()), mode); err != nil {
		return err
	}
	owner := application.Store{Root: filepath.Join(filepath.Dir(path), ".baseharbor", "apps")}
	_, err := owner.Sync(m)
	return err
}

func mustWriteInitializedAuthoredManifest(t *testing.T, path string, m application.Manifest) {
	t.Helper()
	if err := writeInitializedAuthoredManifest(t, path, m, 0600); err != nil {
		t.Fatal(err)
	}
}
